def craft_bgp_open_message(my_as, my_bgp_id, hold_time=90, router_id='127.0.0.1'):
    """Crafts a standard BGP OPEN message to establish a session."""
    # BGP Header: Marker (16 bytes), Length (2 bytes), Type (1 byte)
    marker = b'\xff' * 16
    msg_length = 29  # 19 (header) + 10 (OPEN payload)
    msg_type = 1  # OPEN
    
    # OPEN Message Payload
    version = 4
    my_as = struct.pack('!H', my_as)
    hold_time = struct.pack('!H', hold_time)
    router_id = socket.inet_aton(router_id)
    opt_param_length = 0
    
    payload = struct.pack('!BB', version, opt_param_length) + my_as + hold_time + router_id
    
    return marker + struct.pack('!HB', msg_length, msg_type) + payload

